SET ROLE service_role;
DO $$
DECLARE customer uuid:='10000000-0000-4000-8000-000000000001'; admin uuid:='10000000-0000-4000-8000-000000000002'; other_customer uuid:='10000000-0000-4000-8000-000000000003';
 c jsonb; orphan jsonb; replay jsonb; k uuid:=gen_random_uuid(); case_uuid uuid; loan uuid; l jsonb; payoff bigint;
 draft jsonb:='{"reason":"ungraded","cardName":"未鑑定テストカード","cardNumber":"001","condition":"傷あり","notes":"LINEで写真確認","requestedAmount":"300000","consent":true}';
BEGIN
 c:=lending_support_create(customer,draft,k);case_uuid:=(c->>'id')::uuid;
 replay:=lending_support_create(customer,draft,k);ASSERT c=replay,'idempotent create';
 ASSERT jsonb_array_length(lending_support_list(other_customer)->'cases')=0,'owner list isolation';
 ASSERT NOT (c ? 'contact_label'),'private contact hidden';
 BEGIN PERFORM lending_support_create(customer,draft||jsonb_build_object('userId',other_customer),gen_random_uuid());RAISE EXCEPTION 'test failed';EXCEPTION WHEN raise_exception THEN ASSERT SQLERRM='forbidden';END;
 BEGIN PERFORM lending_support_command(other_customer,case_uuid,'cancel','{}',gen_random_uuid(),1);RAISE EXCEPTION 'test failed';EXCEPTION WHEN raise_exception THEN ASSERT SQLERRM='not_found';END;
 BEGIN PERFORM lending_support_command(customer,case_uuid,'review','{"message":"pretend admin"}',gen_random_uuid(),1);RAISE EXCEPTION 'test failed';EXCEPTION WHEN raise_exception THEN ASSERT SQLERRM='forbidden';END;
 c:=lending_support_command(admin,case_uuid,'review','{"message":"写真を確認中"}',gen_random_uuid(),1);
 BEGIN PERFORM lending_support_command(admin,case_uuid,'decline','{"message":"stale"}',gen_random_uuid(),1);RAISE EXCEPTION 'test failed';EXCEPTION WHEN raise_exception THEN ASSERT SQLERRM='version_conflict';END;
 c:=lending_support_command(admin,case_uuid,'offer','{"amountJpy":300000,"valuationJpy":500000,"message":"現物検品前の個別見積もり"}',gen_random_uuid(),2);
 BEGIN PERFORM lending_support_command(admin,case_uuid,'accept','{"amountJpy":300000,"deposit":"mail","termsAccepted":true}',gen_random_uuid(),3);RAISE EXCEPTION 'test failed';EXCEPTION WHEN raise_exception THEN ASSERT SQLERRM='consent_or_offer_required';END;
 BEGIN PERFORM lending_support_command(customer,case_uuid,'accept','{"amountJpy":300000,"deposit":"mail"}',gen_random_uuid(),3);RAISE EXCEPTION 'test failed';EXCEPTION WHEN raise_exception THEN ASSERT SQLERRM='consent_or_offer_required';END;
 k:=gen_random_uuid(); c:=lending_support_command(customer,case_uuid,'accept','{"amountJpy":300000,"deposit":"mail","termsAccepted":true}',k,3);
 replay:=lending_support_command(customer,case_uuid,'accept','{"amountJpy":300000,"deposit":"mail","termsAccepted":true}',k,3);ASSERT c=replay;
 loan:=(c->>'loan_id')::uuid;ASSERT loan IS NOT NULL;
 ASSERT (SELECT count(*)=1 FROM lending_loans WHERE lending_loans.id=loan AND cert_number IS NULL),'genuine uncertified loan';
 ASSERT (SELECT count(*)=1 FROM lending_quotes WHERE support_case_id=case_uuid AND source='support' AND card_uid IS NULL AND buy_price_jpy IS NULL),'no fabricated PSA valuation';
 PERFORM lending_command(admin,loan,'receive','{"location":"TEST VAULT","inspected":true}',gen_random_uuid(),1);
 BEGIN PERFORM lending_command(admin,loan,'offer','{"amountJpy":300000,"monthlyRateBps":200}',gen_random_uuid(),2);RAISE EXCEPTION 'test failed';EXCEPTION WHEN raise_exception THEN ASSERT SQLERRM='manual_evidence_required';END;
 PERFORM lending_command(admin,loan,'offer','{"amountJpy":300000,"monthlyRateBps":200,"manualValuationJpy":500000,"manualCapJpy":300000,"reason":"現物状態と市場価格を確認"}',gen_random_uuid(),2);
 BEGIN PERFORM lending_command(admin,loan,'fund','{"amountJpy":300000,"reference":"case-fund-before-consent"}',gen_random_uuid(),3);RAISE EXCEPTION 'test failed';EXCEPTION WHEN raise_exception THEN ASSERT SQLERRM='invalid_transition';END;
 PERFORM lending_command(customer,loan,'accept','{"termsAccepted":true}',gen_random_uuid(),3);
 PERFORM lending_command(admin,loan,'fund','{"amountJpy":300000,"reference":"case-fund-001"}',gen_random_uuid(),4);
 ASSERT (lending_account_summary(customer)->>'outstandingJpy')::bigint>=300000,'shared balance includes manual loan';
 SELECT item INTO l FROM jsonb_array_elements(lending_list(customer)->'loans') item WHERE item->>'id'=loan::text;
 ASSERT l->>'card_name'='未鑑定テストカード';ASSERT l->>'cert_number' IS NULL;
 ASSERT (SELECT item->>'loan_status'='active' FROM jsonb_array_elements(lending_support_list(customer)->'cases') item WHERE item->>'id'=case_uuid::text),'case derives actual contract status';
 payoff:=(l->>'payoff_jpy')::bigint;
 PERFORM lending_command(customer,loan,'report_repayment','{}',gen_random_uuid(),5);
 PERFORM lending_command(admin,loan,'confirm_repayment',jsonb_build_object('amountJpy',payoff,'reference','case-repay-001'),gen_random_uuid(),6);
 PERFORM lending_command(admin,loan,'return','{"reference":"case-return-001"}',gen_random_uuid(),7);
 ASSERT (SELECT status='returned' AND principal_jpy=0 FROM lending_loans WHERE lending_loans.id=loan);
 orphan:=lending_support_create(admin,draft||'{"contactLabel":"LINE受付テスト"}',gen_random_uuid());
 ASSERT orphan->>'user_id' IS NULL,'unlinked admin case';
 BEGIN PERFORM lending_support_command(customer,(orphan->>'id')::uuid,'cancel','{}',gen_random_uuid(),1);RAISE EXCEPTION 'test failed';EXCEPTION WHEN raise_exception THEN ASSERT SQLERRM='not_found';END;
 orphan:=lending_support_command(admin,(orphan->>'id')::uuid,'link',jsonb_build_object('userId',other_customer),gen_random_uuid(),1);
 ASSERT jsonb_array_length(lending_support_list(other_customer)->'cases')=1;
 BEGIN PERFORM lending_support_command(admin,(orphan->>'id')::uuid,'link',jsonb_build_object('userId',customer),gen_random_uuid(),2);RAISE EXCEPTION 'test failed';EXCEPTION WHEN raise_exception THEN ASSERT SQLERRM='customer_link_invalid';END;
 RAISE NOTICE 'Case ownership, admin-only linking, consent, idempotency, versions, manual evidence, balances and repayment/return passed.';
END $$;
RESET ROLE;
SET ROLE authenticated;
DO $$ BEGIN
 BEGIN PERFORM public.lending_support_list('10000000-0000-4000-8000-000000000002');RAISE EXCEPTION 'unsafe RPC exposed';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM id FROM public.lending_support_cases;RAISE EXCEPTION 'unsafe table exposed';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
END $$;
RESET ROLE;
